import{_ as o,C as s,o as i,c as n,aj as e,G as a}from"./chunks/framework.BwH0p-pt.js";const b=JSON.parse('{"title":"Filters & Saved Views","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/products/filters-and-views.md","filePath":"3.0/products/filters-and-views.md","lastUpdated":1785836850000}'),l={name:"3.0/products/filters-and-views.md"};function d(h,t,c,p,u,g){const r=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="filters-saved-views" tabindex="-1">Filters &amp; Saved Views <a class="header-anchor" href="#filters-saved-views" aria-label="Permalink to &quot;Filters &amp; Saved Views&quot;">​</a></h1><p>Large catalogs are only useful if you can find things fast. UnoPim 3.0 turns the product grid into a workbench: filter by category, completeness, dates, product properties, or any attribute value — then save the whole setup as a named view and come back to it with one click.</p><p>Typical uses: <em>&quot;Enabled products in the Winter category below 80% completeness&quot;</em>, <em>&quot;Everything updated this week&quot;</em>, or <em>&quot;All shirts with no brand filled in&quot;</em>.</p><h2 id="filter-the-product-grid" tabindex="-1">Filter the product grid <a class="header-anchor" href="#filter-the-product-grid" aria-label="Permalink to &quot;Filter the product grid&quot;">​</a></h2><ol><li>Go to <strong>Catalog → Products</strong>.</li><li>Click <strong>Filter</strong> above the grid. The <strong>Apply Filters</strong> drawer opens.</li><li>Set the filters you need. Common ones — such as SKU, Name, Attribute Family, Status, Type, and Categories — are shown by default.</li><li>Click <strong>Apply</strong>. The grid reloads with only the matching products.</li></ol><p>Each active filter appears as a <strong>chip</strong> above the grid, so you always see exactly what is narrowing the list. Remove a single chip to drop that filter, or use <strong>Clear all filters</strong> to start fresh.</p>',6)),a(r,{src:"/assets/3.0/images/products/filter-drawer.png",alt:"Apply Filters drawer with active filter chips above the product grid"}),t[1]||(t[1]=e('<h2 id="add-more-filters" tabindex="-1">Add more filters <a class="header-anchor" href="#add-more-filters" aria-label="Permalink to &quot;Add more filters&quot;">​</a></h2><p>Click <strong>Add Filter</strong> in the drawer to pick from everything else that is filterable:</p><table tabindex="0"><thead><tr><th>Filter</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Categories</strong></td><td>Products in (or not in) the categories you pick from the category tree.</td></tr><tr><td><strong>Completeness</strong></td><td>Products above, below, equal to, or between completeness percentages.</td></tr><tr><td><strong>Created / Updated dates</strong></td><td>Products created or updated before, after, or between dates.</td></tr><tr><td><strong>Product properties</strong></td><td>Status (Enabled/Disabled), Attribute Family, Type (Simple/Configurable).</td></tr><tr><td><strong>Attribute values</strong></td><td>Any attribute marked <em>filterable</em> — colour, brand, price, launch date, and so on.</td></tr></tbody></table><h2 id="operators-match-the-data-type" tabindex="-1">Operators match the data type <a class="header-anchor" href="#operators-match-the-data-type" aria-label="Permalink to &quot;Operators match the data type&quot;">​</a></h2><p>Every filter offers operators that fit its type of data, so conditions read the way you would say them:</p><table tabindex="0"><thead><tr><th>Data type</th><th>Operators</th></tr></thead><tbody><tr><td>Text</td><td>Contains, Equals, Is empty, Is not empty</td></tr><tr><td>Numbers, price, completeness</td><td>Equals, Less than, Greater than, Between, Is empty, Is not empty</td></tr><tr><td>Dates</td><td>Before, After, Between, Is empty, Is not empty</td></tr><tr><td>Select / multiselect / categories</td><td>In list, Not in list, Is empty, Is not empty</td></tr><tr><td>Yes/No</td><td>Equals</td></tr></tbody></table><p>The <em>Is empty</em> operator is a quiet workhorse: it finds every product where a value is still missing — perfect for enrichment to-do lists.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If an attribute does not appear in <strong>Add Filter</strong>, it is not marked as filterable yet. Edit the attribute under <strong>Catalog → Attributes</strong> and switch <strong>Is Filterable</strong> on.</p></div><h2 id="save-a-view-and-reuse-it" tabindex="-1">Save a view and reuse it <a class="header-anchor" href="#save-a-view-and-reuse-it" aria-label="Permalink to &quot;Save a view and reuse it&quot;">​</a></h2><p>Once a filter and column combination works for you, keep it:</p><ol><li>Set up your filters, and arrange the grid columns the way you like (via <strong>Columns</strong>).</li><li>Open the <strong>Saved Filters</strong> menu in the grid toolbar.</li><li>Enter a name — for example <em>Winter enrichment backlog</em>.</li><li>Optionally switch on <strong>Share with all admins</strong> so your whole team can use it.</li><li>Click <strong>Save filter</strong>.</li></ol><p>A saved view remembers your filters, columns, sorting, page size, and the channel and locale you were working in. Selecting it later restores the grid exactly as you left it. When you change something while a view is applied, the toolbar shows <em>Unsaved changes</em> so you know the grid no longer matches the stored view.</p>',12)),a(r,{src:"/assets/3.0/images/products/saved-views.png",alt:"Saved Filters menu with named views and the share option"}),t[2]||(t[2]=e('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create one shared view per recurring team task — <em>Missing images</em>, <em>New this week</em>, <em>Ready to publish</em>. It replaces re-explaining filter recipes in chat.</p></div><h2 id="act-on-everything-that-matches" tabindex="-1">Act on everything that matches <a class="header-anchor" href="#act-on-everything-that-matches" aria-label="Permalink to &quot;Act on everything that matches&quot;">​</a></h2><p>Filters and mass actions work together across pages:</p><ol><li>Filter the grid down to the products you want to change.</li><li>Tick the select-all box. UnoPim offers <strong>Select all</strong> matching records — not just the rows on the current page.</li><li>Choose the mass action: bulk edit, enable/disable, or delete.</li></ol><p>For large selections, the work runs <strong>in the background</strong> — you can keep working while UnoPim processes the change, and follow progress on the Job Tracker.</p><h2 id="related-reading" tabindex="-1">Related reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related reading&quot;">​</a></h2><ul><li><strong><a href="./simple.html#working-with-the-products-listing">Simple Product — Working with the Products listing</a></strong> — columns, bulk edit, and quick export basics.</li><li><strong><a href="./../attribute/product-attribute.html">Product Attribute</a></strong> — how to make an attribute filterable.</li><li><strong><a href="./variants.html">Product Variants</a></strong> — structure catalogs that vary by colour, size, and more.</li></ul>',7))])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
